create table if not exists public.marketplace_orders (
 id uuid primary key default gen_random_uuid(), order_number text not null unique default ('PLT-'||to_char(now(),'YYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),
 buyer_user_id uuid not null references auth.users(id) on delete restrict, store_id uuid not null references public.stores(id) on delete restrict,
 status text not null default 'pending_payment' check(status in ('pending_payment','payment_review','paid','processing','ready_for_pickup','shipped','completed','cancelled','refund_requested','refunded','disputed')),
 payment_status text not null default 'unpaid' check(payment_status in ('unpaid','submitted','verified','rejected','refunded')), currency_code char(3) not null default 'IDR',
 subtotal numeric(14,2) not null check(subtotal>=0), delivery_fee numeric(14,2) not null default 0 check(delivery_fee>=0), total_amount numeric(14,2) not null check(total_amount>=0),
 buyer_name text not null,buyer_phone text not null,delivery_method text not null default 'pickup' check(delivery_method in ('pickup','delivery')),delivery_address text not null default '',buyer_note text not null default '',
 reserved_until timestamptz not null default now()+interval '20 minutes',created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.marketplace_order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.marketplace_orders(id) on delete cascade,product_id uuid not null references public.products(id) on delete restrict,variant_id uuid not null references public.product_variants(id) on delete restrict,product_name text not null,variant_name text not null default '',quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null check(unit_price>=0),line_total numeric(14,2) not null check(line_total>=0),created_at timestamptz not null default now());
create table if not exists public.marketplace_payment_records (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.marketplace_orders(id) on delete cascade,buyer_user_id uuid not null references auth.users(id) on delete restrict,payment_method text not null check(payment_method in ('bank_transfer','cash_on_pickup','cash_on_delivery')),amount numeric(14,2) not null check(amount>0),payer_reference text not null default '',proof_path text not null default '',status text not null default 'submitted' check(status in ('submitted','verified','rejected','refunded')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.marketplace_order_events (id bigint generated always as identity primary key,order_id uuid not null references public.marketplace_orders(id) on delete cascade,actor_user_id uuid references auth.users(id),event_type text not null,note text not null default '',created_at timestamptz not null default now());
create index if not exists marketplace_orders_buyer_idx on public.marketplace_orders(buyer_user_id,created_at desc);
create index if not exists marketplace_orders_store_idx on public.marketplace_orders(store_id,created_at desc);
create index if not exists marketplace_items_order_idx on public.marketplace_order_items(order_id);
create index if not exists marketplace_payments_order_idx on public.marketplace_payment_records(order_id,created_at desc);
alter table public.marketplace_orders enable row level security;alter table public.marketplace_order_items enable row level security;alter table public.marketplace_payment_records enable row level security;alter table public.marketplace_order_events enable row level security;
revoke all on public.marketplace_orders,public.marketplace_order_items,public.marketplace_payment_records,public.marketplace_order_events from anon,authenticated;
grant select on public.marketplace_orders,public.marketplace_order_items,public.marketplace_payment_records,public.marketplace_order_events to authenticated;
create policy marketplace_orders_participant_read on public.marketplace_orders for select to authenticated using(buyer_user_id=(select auth.uid()) or exists(select 1 from public.store_members sm where sm.store_id=marketplace_orders.store_id and sm.user_id=(select auth.uid()) and sm.member_status='active'));
create policy marketplace_items_participant_read on public.marketplace_order_items for select to authenticated using(exists(select 1 from public.marketplace_orders o where o.id=order_id and (o.buyer_user_id=(select auth.uid()) or exists(select 1 from public.store_members sm where sm.store_id=o.store_id and sm.user_id=(select auth.uid()) and sm.member_status='active'))));
create policy marketplace_payments_participant_read on public.marketplace_payment_records for select to authenticated using(buyer_user_id=(select auth.uid()) or exists(select 1 from public.marketplace_orders o join public.store_members sm on sm.store_id=o.store_id where o.id=order_id and sm.user_id=(select auth.uid()) and sm.member_status='active'));
create policy marketplace_events_participant_read on public.marketplace_order_events for select to authenticated using(exists(select 1 from public.marketplace_orders o where o.id=order_id and (o.buyer_user_id=(select auth.uid()) or exists(select 1 from public.store_members sm where sm.store_id=o.store_id and sm.user_id=(select auth.uid()) and sm.member_status='active'))));
